"""
Editorial Voice — Opinion injection per trigger type.

Each trigger type gets a personality with context-aware opinions.
"""

import logging
from typing import Dict, List, Optional, Any
from datetime import datetime

logger = logging.getLogger(__name__)


class EditorialVoice:
    """Inject personality/opinions into messages."""

    # Voice pools per trigger type and market state
    VOICE_POOLS = {
        "cross_platform": {
            "big_divergence": [
                "Big divergence. One of these markets is wrong.",
                "Spreads are blown out. Arb opportunity.",
                "Thick divergence — reality check time.",
            ],
            "mild_divergence": [
                "Mild divergence. Nothing screaming yet.",
                "Slight edge here. Could tighten.",
                "Some separation between markets.",
            ],
            "stale_divergence": [
                "Divergence is stale — markets may have already repriced.",
                "Old spread. Probably already arbitraged.",
            ],
        },
        "portfolio": {
            "excellent": [
                "Good day. Portfolio's running.",
                "Solid gains. Steady hand.",
                "Portfolio's firing on all cylinders.",
            ],
            "good": [
                "Up nicely today. Keep it up.",
                "Gains are sticking. Good momentum.",
            ],
            "flat": [
                "Flat day. Markets are grinding.",
                "No movement. Just noise.",
            ],
            "bad": [
                "Rough patch. Check your stops.",
                "Tough day. Volatility's biting.",
            ],
            "terrible": [
                "Heavy day. Buckle up for volatility.",
                "Significant drawdown. Hang tight.",
            ],
        },
        "x_signals": {
            "strong": [
                "Strong signal. This feels real.",
                "High conviction here.",
                "Signal is loud and clear.",
            ],
            "moderate": [
                "New signal on [topic]. Worth watching.",
                "Decent signal. On the radar.",
            ],
            "weak": [
                "Noise signal. Low confidence.",
                "Weak signal. Probably churn.",
            ],
        },
        "edge": {
            "fat": [
                "Fat edge. Worth a deep look.",
                "Juicy edge here. Dig in.",
                "Thick edge. Opportunity time.",
            ],
            "mild": [
                "Mild edge. Keeping it on radar.",
                "Thin edge. Could tighten soon.",
            ],
            "thin": [
                "Thin edge. Not worth the friction.",
                "Edge is razor thin.",
            ],
        },
        "morning": {
            "monday": [
                "New week. Here's the lay of the land.",
                "Monday morning. Week's open for business.",
                "Fresh week. What's new out there.",
            ],
            "friday": [
                "Friday rundown. What matters before the close.",
                "Friday close. Have a good weekend.",
                "Last trading day. Here's the recap.",
            ],
            "other": [
                "Daily digest.",
                "Market snapshot.",
                "What's moving today.",
            ],
        },
        "conflicts": {
            "heavy": [
                "Tomorrow's a mess. Multiple overlaps.",
                "Heads up — couple things hitting together.",
            ],
            "light": [
                "Couple things on the radar today.",
            ],
        },
        "meeting": {
            "imminent": [
                "Heads up — you've got a meeting in [minutes].",
                "Reminder: Meeting in [minutes].",
            ],
        },
    }

    def __init__(self):
        """Initialize EditorialVoice."""
        logger.debug("EditorialVoice initialized")

    def inject_opinion(self, trigger_type: str, data: Dict[str, Any]) -> Optional[str]:
        """
        Inject an opinion based on trigger type and market state.

        Args:
            trigger_type: Type of trigger
            data: Market/portfolio data for context

        Returns:
            Opinion string or None
        """

        if trigger_type == "cross_platform":
            return self._opinion_cross_platform(data)
        elif trigger_type == "portfolio":
            return self._opinion_portfolio(data)
        elif trigger_type == "x_signals":
            return self._opinion_x_signals(data)
        elif trigger_type == "edge":
            return self._opinion_edge(data)
        elif trigger_type == "morning":
            return self._opinion_morning(data)
        elif trigger_type == "conflicts":
            return self._opinion_conflicts(data)
        elif trigger_type == "meeting":
            return self._opinion_meeting(data)
        else:
            logger.debug(f"No opinion pool for trigger type: {trigger_type}")
            return None

    def _opinion_cross_platform(self, data: Dict[str, Any]) -> Optional[str]:
        """Opinion for Kalshi vs Polymarket divergence."""
        spread = data.get("spread", 0)
        age_hours = data.get("age_hours", 0)

        # Stale divergence (6+ hours)
        if age_hours >= 6:
            return self._pick_random_opinion("stale_divergence")

        # Size-based classification
        if spread >= 5.0:
            return self._pick_random_opinion("big_divergence")
        elif spread >= 2.0:
            return self._pick_random_opinion("mild_divergence")

        return None

    def _opinion_portfolio(self, data: Dict[str, Any]) -> Optional[str]:
        """Opinion for portfolio P&L."""
        daily_pnl = data.get("daily_pnl", 0)

        if daily_pnl >= 15:
            return self._pick_random_opinion("excellent")
        elif daily_pnl >= 5:
            return self._pick_random_opinion("good")
        elif daily_pnl >= -5:
            return self._pick_random_opinion("flat")
        elif daily_pnl >= -15:
            return self._pick_random_opinion("bad")
        else:
            return self._pick_random_opinion("terrible")

    def _opinion_x_signals(self, data: Dict[str, Any]) -> Optional[str]:
        """Opinion for social signal scanner."""
        confidence = data.get("confidence", 0.0)
        position_match = data.get("position_match", False)
        topic = data.get("topic", "")

        # Strong signal
        if confidence >= 0.85 and position_match:
            return self._pick_random_opinion("strong")
        # Moderate signal
        elif confidence >= 0.70:
            msg = self._pick_random_opinion("moderate")
            if msg and topic:
                msg = msg.replace("[topic]", topic)
            return msg
        # Weak signal
        else:
            return self._pick_random_opinion("weak")

    def _opinion_edge(self, data: Dict[str, Any]) -> Optional[str]:
        """Opinion for Kalshi edge detection."""
        edge_size = data.get("edge_size", 0)

        if edge_size >= 3.0:
            return self._pick_random_opinion("fat")
        elif edge_size >= 1.0:
            return self._pick_random_opinion("mild")
        else:
            return self._pick_random_opinion("thin")

    def _opinion_morning(self, data: Dict[str, Any]) -> Optional[str]:
        """Opinion for morning brief."""
        now = datetime.now()
        day_name = now.strftime("%A").lower()

        if day_name == "monday":
            return self._pick_random_opinion("monday")
        elif day_name == "friday":
            return self._pick_random_opinion("friday")
        else:
            return self._pick_random_opinion("other")

    def _opinion_conflicts(self, data: Dict[str, Any]) -> Optional[str]:
        """Opinion for overlapping triggers."""
        conflict_count = data.get("conflict_count", 1)

        if conflict_count >= 2:
            return self._pick_random_opinion("heavy")
        else:
            return self._pick_random_opinion("light")

    def _opinion_meeting(self, data: Dict[str, Any]) -> Optional[str]:
        """Opinion for upcoming meeting."""
        minutes_away = data.get("minutes_away", 0)

        if minutes_away < 30:
            msg = self._pick_random_opinion("imminent")
            if msg and minutes_away:
                msg = msg.replace("[minutes]", str(int(minutes_away)))
            return msg

        return None

    def _pick_random_opinion(self, pool_key: str) -> Optional[str]:
        """Pick random opinion from a pool."""
        # Parse pool_key format: "trigger_type.subpool"
        parts = pool_key.split(".")
        if len(parts) == 1:
            # Try to find in any trigger type's subpool
            for trigger_type, subpools in self.VOICE_POOLS.items():
                if pool_key in subpools:
                    opinions = subpools[pool_key]
                    if opinions:
                        import random

                        return random.choice(opinions)
        else:
            trigger_type, subpool = parts
            if trigger_type in self.VOICE_POOLS:
                opinions = self.VOICE_POOLS[trigger_type].get(subpool, [])
                if opinions:
                    import random

                    return random.choice(opinions)

        return None

    def add_opinion_pool(
        self, trigger_type: str, subpool_name: str, opinions: List[str]
    ) -> None:
        """
        Add or extend opinion pool at runtime.

        Args:
            trigger_type: Trigger type (e.g., 'portfolio')
            subpool_name: Subpool name (e.g., 'excellent')
            opinions: List of opinion strings
        """
        if trigger_type not in self.VOICE_POOLS:
            self.VOICE_POOLS[trigger_type] = {}

        if subpool_name not in self.VOICE_POOLS[trigger_type]:
            self.VOICE_POOLS[trigger_type][subpool_name] = []

        self.VOICE_POOLS[trigger_type][subpool_name].extend(opinions)
        logger.debug(
            f"Added {len(opinions)} opinions to {trigger_type}.{subpool_name}"
        )

    def add_trigger_voice(self, trigger_type: str, voice_dict: Dict[str, List[str]]) -> None:
        """
        Add complete voice definition for new trigger type.

        Args:
            trigger_type: New trigger type name
            voice_dict: Dict mapping subpool names to opinion lists
        """
        self.VOICE_POOLS[trigger_type] = voice_dict
        logger.info(f"Added voice definition for trigger type: {trigger_type}")

    def list_available_voices(self) -> Dict[str, List[str]]:
        """
        List all available voice pools.

        Returns:
            Dict mapping trigger_type to list of subpool names
        """
        return {
            trigger_type: list(subpools.keys())
            for trigger_type, subpools in self.VOICE_POOLS.items()
        }

"""
Micro-Initiations — Ambient awareness pings.

Unprompted messages when conditions met (quiet market, good streak, absence detected).
Max 2/week, skip busy days, no repeats within 2 weeks.
"""

import hashlib
import json
import logging
from datetime import datetime, timezone, timedelta
from pathlib import Path
from typing import Dict, Any, Optional, List

logger = logging.getLogger(__name__)


class MicroInitiations:
    """Generate unprompted ambient awareness messages."""

    # US Holiday calendar
    HOLIDAYS = {
        (1, 1): "New Year's Day",
        (1, 20): "MLK Day",
        (2, 17): "Presidents' Day",
        (3, 17): "St. Patrick's Day",
        (5, 26): "Memorial Day",
        (7, 4): "Independence Day",
        (9, 1): "Labor Day",
        (10, 13): "Columbus Day",
        (11, 11): "Veterans Day",
        (11, 27): "Thanksgiving",
        (12, 25): "Christmas",
    }

    # Micro-initiation pools
    MICRO_POOLS = {
        "QUIET_MARKET": {
            "condition": lambda ctx: ctx.get("vol", 0) < 0.3 and ctx.get("trade_count", 0) == 0,
            "messages": [
                "Quiet day. Markets are sleeping.",
                "No action today. Enjoy the peace.",
                "Markets in hibernation.",
            ],
        },
        "WEEKEND": {
            "condition": lambda ctx: ctx.get("is_weekend", False) and ctx.get("has_meetings", False) is False,
            "messages": [
                "Weekend vibes. You're off the hook.",
                "Enjoy your weekend — markets are closed.",
                "Time to rest.",
            ],
        },
        "MONDAY": {
            "condition": lambda ctx: ctx.get("is_monday", False),
            "messages": [
                "Monday morning. Week's open for business.",
                "Fresh week. What's new.",
                "Back to work.",
            ],
        },
        "FRIDAY": {
            "condition": lambda ctx: ctx.get("is_friday", False),
            "messages": [
                "Friday close. Have a good weekend.",
                "Last trading day. Here's the recap.",
                "End of week.",
            ],
        },
        "HOLIDAY_AWARENESS": {
            "condition": lambda ctx: ctx.get("is_holiday", False),
            "messages": [
                "Holiday today. Markets are light.",
                "Market holiday — slow day.",
                "Holiday. Expect thin trading.",
            ],
        },
        "GOOD_STREAK": {
            "condition": lambda ctx: ctx.get("consecutive_positive_days", 0) >= 5,
            "messages": [
                "On a roll. Good week for you.",
                "Winning streak. Keep it up.",
                "You're crushing it.",
            ],
        },
        "BAD_STREAK": {
            "condition": lambda ctx: ctx.get("consecutive_negative_days", 0) >= 5,
            "messages": [
                "Rough stretch. It'll turn around.",
                "Tough week. Hang in there.",
                "Volatility biting. Stay disciplined.",
            ],
        },
        "ABSENCE": {
            "condition": lambda ctx: ctx.get("user_absence_hours", 0) >= 24,
            "messages": [
                "Checking in. Things have been quiet.",
                "Haven't heard from you. All good?",
                "Missed you. Thought I'd check in.",
            ],
        },
    }

    # Cadence limits
    MICRO_CADENCE = {
        "max_per_week": 2,  # Max 2 micro-initiations per week
        "skip_if_alerts_today": 3,  # Skip if 3+ regular alerts already sent
        "no_repeat_days": 14,  # No repeats within 2 weeks
    }

    def __init__(self, state_dir: Path):
        """Initialize MicroInitiations."""
        self.state_dir = Path(state_dir)
        self.state_dir.mkdir(parents=True, exist_ok=True)
        self.micro_state_file = self.state_dir / "micro_state.json"
        self._load_micro_state()
        logger.debug("MicroInitiations initialized")

    def evaluate_pools(self, context: Dict[str, Any]) -> Optional[str]:
        """
        Evaluate all pools and return a message if conditions met.

        Args:
            context: Market/user state

        Returns:
            Message string or None
        """

        # Get current day info
        now = datetime.now(timezone.utc)
        context["is_weekend"] = now.weekday() in (5, 6)
        context["is_monday"] = now.weekday() == 0
        context["is_friday"] = now.weekday() == 4
        context["is_holiday"] = self._is_holiday(now)

        # Evaluate all pools in order of priority
        pool_order = [
            "ABSENCE",
            "HOLIDAY_AWARENESS",
            "MONDAY",
            "FRIDAY",
            "GOOD_STREAK",
            "BAD_STREAK",
            "WEEKEND",
            "QUIET_MARKET",
        ]

        for pool_name in pool_order:
            if pool_name not in self.MICRO_POOLS:
                continue

            pool = self.MICRO_POOLS[pool_name]
            try:
                if pool["condition"](context):
                    message = self._pick_random_message(pool["messages"])
                    logger.info(f"Micro-initiation condition met: {pool_name}")
                    return message
            except Exception as e:
                logger.warning(f"Error evaluating pool {pool_name}: {e}")

        return None

    def should_send_micro_initiation(
        self, alert_count_today: int = 0
    ) -> bool:
        """
        Check if we should send a micro-initiation (cadence check).

        Args:
            alert_count_today: Number of regular alerts sent today

        Returns:
            True if we can send, False if cadence limits reached
        """

        # Skip if already sent 3+ alerts today
        if alert_count_today >= self.MICRO_CADENCE["skip_if_alerts_today"]:
            logger.debug(f"Skipping micro-initiation: {alert_count_today} alerts already sent")
            return False

        # Check weekly cadence
        week_sends = self._get_week_sends()
        if len(week_sends) >= self.MICRO_CADENCE["max_per_week"]:
            logger.debug(f"Skipping micro-initiation: {len(week_sends)} sent this week (limit: {self.MICRO_CADENCE['max_per_week']})")
            return False

        # Check for repeats within 2 weeks
        if self._has_recent_repeat():
            logger.debug(f"Skipping micro-initiation: repeat within {self.MICRO_CADENCE['no_repeat_days']} days")
            return False

        return True

    def _is_holiday(self, dt: datetime) -> bool:
        """Check if date is US holiday."""
        return (dt.month, dt.day) in self.HOLIDAYS

    def _get_holiday_name(self, dt: datetime) -> Optional[str]:
        """Get holiday name if applicable."""
        return self.HOLIDAYS.get((dt.month, dt.day))

    def _pick_random_message(self, messages: List[str]) -> str:
        """Pick random message from list."""
        import random
        return random.choice(messages)

    def _get_week_sends(self) -> List[str]:
        """Get all sends from past 7 days."""
        now = datetime.now(timezone.utc)
        week_ago = (now - timedelta(days=7)).date()

        sends = []
        for send_date in self.micro_state.get("sends", []):
            send_dt = datetime.fromisoformat(send_date).date()
            if send_dt >= week_ago:
                sends.append(send_date)

        return sends

    def _has_recent_repeat(self) -> bool:
        """Check if any message pool was used within no_repeat_days."""
        now = datetime.now(timezone.utc)
        cutoff = (now - timedelta(days=self.MICRO_CADENCE["no_repeat_days"])).date()

        for pool_name, send_dates in self.micro_state.get("pool_history", {}).items():
            for send_date in send_dates:
                send_dt = datetime.fromisoformat(send_date).date()
                if send_dt >= cutoff:
                    return True

        return False

    def log_send(self, pool_name: str, message: str) -> None:
        """Log a micro-initiation send."""
        now = datetime.now(timezone.utc).isoformat()

        if "sends" not in self.micro_state:
            self.micro_state["sends"] = []

        self.micro_state["sends"].append(now)

        if "pool_history" not in self.micro_state:
            self.micro_state["pool_history"] = {}

        if pool_name not in self.micro_state["pool_history"]:
            self.micro_state["pool_history"][pool_name] = []

        self.micro_state["pool_history"][pool_name].append(now)

        # Keep last 100 sends
        self.micro_state["sends"] = self.micro_state["sends"][-100:]

        self._save_micro_state()
        logger.debug(f"Logged micro-initiation send for pool: {pool_name}")

    def add_pool(
        self, pool_name: str, condition, messages: List[str]
    ) -> None:
        """
        Add custom pool at runtime.

        Args:
            pool_name: Name of pool
            condition: Lambda function that evaluates context
            messages: List of message strings
        """
        self.MICRO_POOLS[pool_name] = {
            "condition": condition,
            "messages": messages,
        }
        logger.info(f"Added custom micro pool: {pool_name}")

    def _load_micro_state(self) -> None:
        """Load micro state from disk."""
        if self.micro_state_file.exists():
            try:
                with open(self.micro_state_file) as f:
                    self.micro_state = json.load(f)
                logger.debug("Loaded micro state")
            except Exception as e:
                logger.warning(f"Failed to load micro state: {e}")
                self.micro_state = {}
        else:
            self.micro_state = {}

    def _save_micro_state(self) -> None:
        """Save micro state to disk."""
        try:
            with open(self.micro_state_file, "w") as f:
                json.dump(self.micro_state, f, indent=2, default=str)
        except Exception as e:
            logger.error(f"Failed to save micro state: {e}")

    def get_summary(self) -> Dict[str, Any]:
        """Get summary of micro-initiation state."""
        week_sends = self._get_week_sends()
        return {
            "cadence_limits": self.MICRO_CADENCE,
            "week_sends_count": len(week_sends),
            "available_pools": list(self.MICRO_POOLS.keys()),
            "pool_sends": self.micro_state.get("pool_history", {}),
        }

"""
Selective Silence — Knowing when NOT to talk.

Content quality checks per trigger. Deliberate silence messages.
Max 1 silence message per day.
"""

import json
import logging
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, Any, Optional

logger = logging.getLogger(__name__)


class SelectiveSilence:
    """Determine if a trigger should be silenced due to low content quality."""

    # Content quality thresholds
    SILENCE_THRESHOLDS = {
        "vol_floor": 0.5,  # % vol for morning silence
        "divergence_age_limit": 3,  # hours
        "divergence_spread_movement": 0.5,  # % spread change required
        "signal_confidence_floor": 0.65,
        "edge_floor": 1.0,  # %
        "portfolio_flat_range": 2.0,  # % P&L range
    }

    def __init__(self, state_dir: Path):
        """Initialize SelectiveSilence."""
        self.state_dir = Path(state_dir)
        self.state_dir.mkdir(parents=True, exist_ok=True)
        self.silence_state_file = self.state_dir / "silence_state.json"
        self._load_silence_state()
        logger.debug("SelectiveSilence initialized")

    def should_silence(self, trigger_type: str, data: Dict[str, Any]) -> bool:
        """
        Determine if trigger should be silenced.

        Args:
            trigger_type: Type of trigger
            data: Market/portfolio data

        Returns:
            True if should silence, False if should send
        """

        if trigger_type == "morning":
            return self._should_silence_morning(data)
        elif trigger_type == "cross_platform":
            return self._should_silence_divergence(data)
        elif trigger_type == "x_signals":
            return self._should_silence_signals(data)
        elif trigger_type == "edge":
            return self._should_silence_edge(data)
        elif trigger_type == "portfolio":
            return self._should_silence_portfolio(data)
        else:
            return False

    def _should_silence_morning(self, data: Dict[str, Any]) -> bool:
        """Silence morning brief if boring."""
        vol = data.get("vol", 0)
        divergence_count = data.get("divergence_count", 0)
        edge_count = data.get("edge_count", 0)

        # All three conditions must be met for silence
        boring = vol < self.SILENCE_THRESHOLDS["vol_floor"]
        no_divergences = divergence_count == 0
        no_edges = edge_count == 0

        if boring and no_divergences and no_edges:
            if self._can_send_silence_message("morning"):
                return True

        return False

    def _should_silence_divergence(self, data: Dict[str, Any]) -> bool:
        """Silence stale divergence."""
        age_hours = data.get("age_hours", 0)
        last_spread = data.get("last_spread", None)
        current_spread = data.get("current_spread", None)

        # Check if stale
        if age_hours >= self.SILENCE_THRESHOLDS["divergence_age_limit"]:
            # Check if spread has moved significantly
            if last_spread and current_spread:
                spread_change = abs(current_spread - last_spread)
                if spread_change < self.SILENCE_THRESHOLDS["divergence_spread_movement"]:
                    if self._can_send_silence_message("cross_platform"):
                        return True

        return False

    def _should_silence_signals(self, data: Dict[str, Any]) -> bool:
        """Silence if all signals are noise."""
        signals = data.get("signals", [])
        confidence_floor = self.SILENCE_THRESHOLDS["signal_confidence_floor"]

        if not signals:
            return False

        # Check if all signals are low confidence and no position matches
        all_low_confidence = all(s.get("confidence", 0) < confidence_floor for s in signals)
        no_position_matches = all(not s.get("position_match", False) for s in signals)

        if all_low_confidence and no_position_matches:
            if self._can_send_silence_message("x_signals"):
                return True

        return False

    def _should_silence_edge(self, data: Dict[str, Any]) -> bool:
        """Silence if all edges are thin."""
        edges = data.get("edges", [])
        edge_floor = self.SILENCE_THRESHOLDS["edge_floor"]

        if not edges:
            return False

        # Check if all edges are below floor
        all_thin = all(e.get("size", 0) < edge_floor for e in edges)

        if all_thin:
            if self._can_send_silence_message("edge"):
                return True

        return False

    def _should_silence_portfolio(self, data: Dict[str, Any]) -> bool:
        """Silence if portfolio is flat."""
        daily_pnl = data.get("daily_pnl", 0)
        position_changes = data.get("position_changes", 0)
        flat_range = self.SILENCE_THRESHOLDS["portfolio_flat_range"]

        # Flat if P&L is within range AND no major position changes
        is_flat = abs(daily_pnl) < flat_range
        no_position_changes = position_changes == 0

        if is_flat and no_position_changes:
            if self._can_send_silence_message("portfolio"):
                return True

        return False

    def _can_send_silence_message(self, trigger_type: str) -> bool:
        """
        Check if we can send silence message for this trigger today.

        Max 1 silence message per day per trigger type.
        """
        today = datetime.now(timezone.utc).date().isoformat()

        if today not in self.silence_state:
            self.silence_state[today] = {}

        if trigger_type in self.silence_state[today]:
            # Already sent silence for this trigger today
            return False

        # Mark as sent
        self.silence_state[today][trigger_type] = True
        self._save_silence_state()

        logger.debug(f"Silence message allowed for {trigger_type} today")
        return True

    def _load_silence_state(self) -> None:
        """Load silence state from disk."""
        if self.silence_state_file.exists():
            try:
                with open(self.silence_state_file) as f:
                    self.silence_state = json.load(f)
                logger.debug(f"Loaded silence state: {self.silence_state}")
            except Exception as e:
                logger.warning(f"Failed to load silence state: {e}")
                self.silence_state = {}
        else:
            self.silence_state = {}

        # Clean old dates (older than 7 days)
        today = datetime.now(timezone.utc).date().isoformat()
        from datetime import timedelta

        cutoff_date = (datetime.fromisoformat(today) - timedelta(days=7)).date().isoformat()
        self.silence_state = {
            date: data
            for date, data in self.silence_state.items()
            if date >= cutoff_date
        }

    def _save_silence_state(self) -> None:
        """Save silence state to disk."""
        try:
            with open(self.silence_state_file, "w") as f:
                json.dump(self.silence_state, f, indent=2)
        except Exception as e:
            logger.error(f"Failed to save silence state: {e}")

    def reset_daily(self) -> None:
        """Reset daily silence counter (called at midnight)."""
        today = datetime.now(timezone.utc).date().isoformat()
        if today in self.silence_state:
            del self.silence_state[today]
        self._save_silence_state()
        logger.info("Daily silence state reset")

    def get_summary(self) -> Dict[str, Any]:
        """Get summary of silence state."""
        return {
            "thresholds": self.SILENCE_THRESHOLDS,
            "silence_counts": {
                date: len(triggers)
                for date, triggers in self.silence_state.items()
            },
        }

"""
Variable Timing — Urgency scoring 0.0-1.0 with time-of-day awareness.

Modifiers: weekend, clustering prevention, daily fatigue, random jitter.
"""

import logging
import random
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, Any, Tuple

logger = logging.getLogger(__name__)


class VariableTiming:
    """Score urgency and determine delivery timing."""

    # Time-of-day thresholds (hour: minimum urgency required to send)
    TIME_OF_DAY_THRESHOLDS = {
        (0, 7): 0.90,  # midnight - 7 AM (sleep time)
        (7, 9): 0.75,  # 7 - 9 AM (morning crunch)
        (9, 22): 0.45,  # 9 AM - 10 PM (daytime, lower bar)
        (22, 23): 0.35,  # 10 - 11 PM (wind-down)
        (23, 24): 0.85,  # 11 PM - midnight (late night, high bar)
    }

    # Urgency modifiers
    WEEKEND_MODIFIER = 0.10  # +0.10 on weekends
    CLUSTERING_PREVENTION = 0.20  # -0.20 if sent <10 min ago
    DAILY_FATIGUE_STEP = 0.20  # +0.20 threshold per 10 messages
    JITTER_RANGE = 0.05  # ±5% random variation

    def __init__(self, state_dir: Path):
        """Initialize VariableTiming."""
        self.state_dir = Path(state_dir)
        self.last_send_time = None
        logger.debug("VariableTiming initialized")

    def compute_base_urgency(self, trigger_type: str, data: Dict[str, Any]) -> float:
        """
        Compute base urgency (0.0-1.0) for trigger type.

        Args:
            trigger_type: Type of trigger
            data: Market/portfolio data

        Returns:
            Base urgency score 0.0-1.0
        """

        if trigger_type == "cross_platform":
            return self._urgency_cross_platform(data)
        elif trigger_type == "portfolio":
            return self._urgency_portfolio(data)
        elif trigger_type == "x_signals":
            return self._urgency_x_signals(data)
        elif trigger_type == "edge":
            return self._urgency_edge(data)
        elif trigger_type == "meeting":
            return self._urgency_meeting(data)
        else:
            return 0.5  # Default medium urgency

    def _urgency_cross_platform(self, data: Dict[str, Any]) -> float:
        """Urgency based on spread size."""
        spread = data.get("spread", 0)
        # 0% spread = 0.0, 5% spread = 0.3, 10%+ spread = 1.0
        urgency = min(1.0, (spread / 10.0) * 0.6)
        return max(0.0, urgency)

    def _urgency_portfolio(self, data: Dict[str, Any]) -> float:
        """Urgency based on portfolio P&L."""
        daily_pnl = data.get("daily_pnl", 0)
        # ±0% = 0.0, ±10% = 0.7, ±15%+ = 1.0
        urgency = min(1.0, (abs(daily_pnl) / 10.0) * 0.7)
        return max(0.0, urgency)

    def _urgency_x_signals(self, data: Dict[str, Any]) -> float:
        """Urgency based on signal confidence and position match."""
        confidence = data.get("confidence", 0.0)
        position_match = data.get("position_match", False)
        # Confidence 0.7-1.0 maps to 0.56-0.8, +0.2 if position match
        confidence_portion = confidence * 0.8
        match_bonus = 0.2 if position_match else 0.0
        urgency = confidence_portion + match_bonus
        return min(1.0, max(0.0, urgency))

    def _urgency_edge(self, data: Dict[str, Any]) -> float:
        """Urgency based on edge size."""
        edge_size = data.get("edge_size", 0)
        # 0% edge = 0.0, 2% edge = 0.32, 5%+ edge = 1.0
        urgency = min(1.0, (edge_size / 5.0) * 0.8)
        return max(0.0, urgency)

    def _urgency_meeting(self, data: Dict[str, Any]) -> float:
        """Urgency based on minutes until meeting."""
        minutes_away = data.get("minutes_away", 120)
        # 120 min away = 0.0, 30 min away = 0.75, 0 min away = 1.0
        urgency = max(0.0, 1.0 - (minutes_away / 120.0))
        return min(1.0, urgency)

    def should_send_now(
        self, adjusted_urgency: float
    ) -> Tuple[bool, int]:
        """
        Determine if we should send now and any delay.

        Args:
            adjusted_urgency: Urgency after engagement modifier

        Returns:
            (should_send_now, delay_seconds)
            If should_send_now=False and delay_seconds=0, hold for next trigger.
        """

        # Get current time-of-day threshold
        now = datetime.now(timezone.utc)
        threshold = self._get_time_of_day_threshold(now)

        # Apply modifiers
        final_threshold = threshold
        final_threshold = self._apply_weekend_modifier(final_threshold, now)
        final_threshold = self._apply_clustering_prevention(final_threshold)
        final_threshold = self._apply_daily_fatigue(final_threshold)

        # Apply jitter
        jitter = random.uniform(-self.JITTER_RANGE, self.JITTER_RANGE)
        final_urgency = adjusted_urgency + jitter

        logger.debug(
            f"Timing check: urgency={final_urgency:.2f} vs threshold={final_threshold:.2f}"
        )

        if final_urgency >= final_threshold:
            self.last_send_time = now
            return (True, 0)
        else:
            return (False, 0)

    def _get_time_of_day_threshold(self, dt: datetime) -> float:
        """Get threshold for current time of day."""
        hour = dt.hour

        for (start_hour, end_hour), threshold in self.TIME_OF_DAY_THRESHOLDS.items():
            if start_hour <= hour < end_hour:
                return threshold

        # Default fallback (shouldn't reach)
        return 0.75

    def _apply_weekend_modifier(self, threshold: float, dt: datetime) -> float:
        """Apply weekend modifier (lower threshold = send more)."""
        # 5 = Saturday, 6 = Sunday
        if dt.weekday() in (5, 6):
            logger.debug(f"Weekend detected, reducing threshold by {self.WEEKEND_MODIFIER}")
            return max(0.0, threshold - self.WEEKEND_MODIFIER)
        return threshold

    def _apply_clustering_prevention(self, threshold: float) -> float:
        """Apply clustering prevention (reduce if recent send)."""
        if self.last_send_time is None:
            return threshold

        now = datetime.now(timezone.utc)
        seconds_since_send = (now - self.last_send_time).total_seconds()

        if seconds_since_send < 600:  # 10 minutes
            adjustment = (600 - seconds_since_send) / 600 * self.CLUSTERING_PREVENTION
            logger.debug(f"Clustering prevention: raising threshold by {adjustment:.2f}")
            return threshold + adjustment

        return threshold

    def _apply_daily_fatigue(self, threshold: float) -> float:
        """Apply daily fatigue modifier (raise threshold if many messages sent today)."""
        # This would typically be passed in from engine tracking
        # For now, simple implementation: could be enhanced with actual message count
        # In real integration, pass message_count_today to engine.process_trigger
        return threshold

    def apply_daily_fatigue_modifier(
        self, threshold: float, message_count_today: int
    ) -> float:
        """Apply fatigue modifier based on today's message count."""
        if message_count_today >= 10:
            fatigue_steps = (message_count_today - 10) // 5
            adjustment = fatigue_steps * self.DAILY_FATIGUE_STEP
            logger.debug(
                f"Daily fatigue: {message_count_today} messages, "
                f"raising threshold by {adjustment:.2f}"
            )
            return threshold + adjustment
        return threshold

    def get_urgency_summary(self) -> Dict[str, Any]:
        """Get summary of current timing state."""
        return {
            "time_of_day_thresholds": self.TIME_OF_DAY_THRESHOLDS,
            "modifiers": {
                "weekend": self.WEEKEND_MODIFIER,
                "clustering_prevention": self.CLUSTERING_PREVENTION,
                "daily_fatigue_step": self.DAILY_FATIGUE_STEP,
                "jitter_range": self.JITTER_RANGE,
            },
        }
